// Build the exact input object for cheap_scraper/linkedin-job-scraper
// (actor id 2rJKkhh7vjpX7pvjg), based on its real input schema.

const pref = items[0]?.json || {};

function splitList(v) {
  return (v || '').split(',').map(s => s.trim()).filter(Boolean);
}

// Map friendly Config values to what the actor expects
const datePostedMap = {
  'any': '',
  'past 24 hours': 'r86400',
  'past day': 'r86400',
  'past week': 'r604800',
  'past month': 'r2592000'
};

const workTypeMap = {
  'remote': 'remote',
  'hybrid': 'hybrid',
  'onsite': 'on-site',
  'on-site': 'on-site'
};

const preferences = {
  keywords: pref.Keywords || 'Software Engineer',
  locations: splitList(pref.Locations || pref.Location || 'Remote'),
  datePosted: pref.DatePosted || 'past week',
  workType: splitList(pref.WorkType || 'remote'),
  employmentType: splitList(pref.EmploymentType || 'full-time'),
  experienceLevel: splitList(pref.ExperienceLevel || ''),
  minSalary: pref.MinSalary || null,
  excludedCompanies: splitList(pref.ExcludedCompanies || ''),
  jobTitleExclude: splitList(pref.JobTitleExclude || ''),
  maxItems: Number(pref.MaxItems) || 150, // pay-per-result billing requires >= 150
  matchThreshold: pref.MatchThreshold || 70,
  baseResumeText: pref.BaseResumeText || '',
  resumeKeywordsRaw: pref.ResumeKeywords || '[]'
};

let resumeKeywords = [];
try {
  resumeKeywords = JSON.parse(preferences.resumeKeywordsRaw);
} catch (e) {
  resumeKeywords = [];
}

const apifyInput = {
  keyword: splitList(preferences.keywords),
  locations: preferences.locations,
  publishedAt: datePostedMap[preferences.datePosted.toLowerCase()] ?? preferences.datePosted,
  jobType: preferences.employmentType,
  workType: preferences.workType.map(w => workTypeMap[w.toLowerCase()] || w),
  experienceLevel: preferences.experienceLevel,
  companyExclude: preferences.excludedCompanies,
  jobTitleExclude: preferences.jobTitleExclude,
  saveOnlyUniqueItems: true,
  enrichCompanyData: true,
  maxItems: preferences.maxItems,
  resumeKeywords: resumeKeywords
};

if (preferences.minSalary) {
  apifyInput.salaryBase = String(preferences.minSalary);
}

return [
  {
    json: {
      preferences,
      apifyInput
    }
  }
];

// Normalize the actor's real output fields into a consistent job object.
const preferences = $('Build Apify Input').first().json.preferences;

const jobs = items.map(({ json: item }) => {
  return {
    json: {
      jobId: String(item.jobId || item.jobUrl || `${item.jobTitle}-${item.companyName}`),
      title: item.jobTitle || '',
      company: item.companyName || '',
      location: item.location || '',
      url: item.jobUrl || '',
      applyUrl: item.applyUrl || '',
      applyType: item.applyType || '',
      postedTime: item.postedTime || '',
      publishedAt: item.publishedAt || '',
      workType: item.workType || '',
      employmentType: item.contractType || '',
      experienceLevel: item.experienceLevel || '',
      sector: item.sector || '',
      salaryInfo: Array.isArray(item.salaryInfo) ? item.salaryInfo.join(' - ') : (item.salaryInfo || ''),
      description: item.jobDescription || '',
      companyInfo: item.companyDescription || '',
      companyWebsite: item.companyWebsite || '',
      companyEmployeeCount: item.companyEmployeeCount || item.companyEmployeeCountRange || '',
      applicationsCount: item.applicationsCount || '',
      dynamicFilterMatch: item.dynamicFilterMatch !== false, // true or undefined = pass
      matchedKeywords: (item.matchedKeywords || []).join(', '),
      unmatchedKeywords: (item.unmatchedKeywords || []).join(', '),
      keywordMatchScorePercentage: item.keywordMatchScorePercentage ?? null,
      preferences
    }
  };
});

// Drop items with no usable ID or description
return jobs.filter(j => j.json.jobId && j.json.description);

// Optional cheap pre-filter using the actor's own dynamicFilterMatch flag
// (set by companySize/industry/org-type/etc. filters in 'Build Apify Input',
// if you configured any there). Jobs that fail are skipped before we ever
// spend an LLM call on them. If you didn't set any dynamic filters, every
// job passes through untouched.
return items.filter(i => i.json.dynamicFilterMatch !== false);

// Input 0 = Pre-filter (Dynamic Match) (all scraped jobs that passed dynamic filters)
// Input 1 = Get Existing Job IDs (already stored jobs)
const scraped = $items('Pre-filter (Dynamic Match)');
const existingRows = $items('Get Existing Job IDs');

const existingIds = new Set(
  existingRows
    .map(r => r.json['Job ID'])
    .filter(Boolean)
    .map(String)
);

const newJobs = scraped.filter(j => !existingIds.has(String(j.json.jobId)));

return newJobs;
